/*
 * Example demonstrating the obsolete sgetmask/ssetmask system calls via syscall(2).
 * WARNING: These calls are typically not available on modern x86-64 systems and are deprecated.
 */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/syscall.h>

// Helper macro for sgetmask/ssetmask bit representation: 
// Signal number N corresponds to the (N-1)th bit (1-based index).
#define SIG_BIT(sig) (1L << ((sig) - 1))

int main() {
    long initial_mask = 0;
    long previous_mask = 0;
    long desired_mask;

    // 1. Retrieve initial mask using syscall(SYS_sgetmask)
    initial_mask = syscall(SYS_sgetmask);

    // Check for failure, which usually means the syscall is unimplemented/unsupported
    if (initial_mask == -1 && initial_mask != 0) {
        fprintf(stderr, "Error: sgetmask syscall failed. This usually indicates the obsolete call is not supported on this architecture.\n");
        return EXIT_FAILURE;
    }
    printf("1. Initial signal mask retrieved: 0x%lx\n", initial_mask);

    // 2. Prepare a mask to block SIGINT (Signal 2)
    desired_mask = initial_mask | SIG_BIT(SIGINT);

    // 3. Set the new mask using syscall(SYS_ssetmask)
    printf("2. Setting new mask (blocking SIGINT).\n");
    previous_mask = syscall(SYS_ssetmask, desired_mask);

    if (previous_mask == -1 && previous_mask != 0) {
        perror("ssetmask failed");
        return EXIT_FAILURE;
    }

    printf("   ssetmask successfully returned the previous mask: 0x%lx\n", previous_mask);

    // 4. Verify the mask change
    long current_mask = syscall(SYS_sgetmask);
    printf("3. Verified current mask: 0x%lx (Should match desired_mask)\n", current_mask);

    // 5. Restore the original state using the mask returned earlier
    printf("4. Restoring original mask: 0x%lx\n", previous_mask);
    syscall(SYS_ssetmask, previous_mask);

    current_mask = syscall(SYS_sgetmask);
    printf("5. Mask after restore: 0x%lx (Should match initial_mask)\n", current_mask);

    return EXIT_SUCCESS;
}
